#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Fill training_feedback_template.hwpx with values from training_feedback.json.

- Replaces {{key}} placeholders across XML files inside the HWPX (zip).
- Applies transformations:
  - 참석자수: digits only
  - 만족도: 'X.X점 (5.0점 만점)'
  - 종합의견: append ' 후속 심화반 검토 요망.'
- Removes layout-cache elements (linesegarray/lineseg) from modified paragraphs.

Output: /root/training_feedback_ready.hwpx
"""

from __future__ import annotations

import io
import json
import os
import re
import shutil
import sys
import tempfile
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple

from xml.etree import ElementTree as ET


TEMPLATE_PATH = Path("/root/training_feedback_template.hwpx")
JSON_PATH = Path("/root/training_feedback.json")
OUTPUT_PATH = Path("/root/training_feedback_ready.hwpx")


HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NSMAP = {"hp": HP_NS}


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def _digits_only(value: str) -> str:
    return re.sub(r"[^0-9]", "", value)


def _format_satisfaction(value) -> str:
    # Accept values like "4.5", 4.5, "4.5/5.0", "4.5점" etc.
    s = str(value)
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)", s)
    if not m:
        return s
    score = float(m.group(1))
    # Keep one decimal (as spec X.X)
    return f"{score:.1f}점 (5.0점 만점)"


def _transform_value(key: str, raw_value) -> str:
    if raw_value is None:
        return ""

    if key == "참석자수":
        return _digits_only(str(raw_value))
    if key == "만족도":
        return _format_satisfaction(raw_value)
    if key == "종합의견":
        # Append required phrase
        base = str(raw_value)
        return base + " 후속 심화반 검토 요망."

    return str(raw_value)


@dataclass
class ReplaceStats:
    files_modified: int = 0
    paragraphs_modified: int = 0
    placeholders_replaced: int = 0
    warnings: List[str] = None

    def __post_init__(self):
        if self.warnings is None:
            self.warnings = []


def _iter_xml_files(root_dir: Path) -> Iterable[Path]:
    for p in root_dir.rglob("*"):
        if p.is_file() and p.suffix.lower() == ".xml":
            yield p


def _get_local(tag: str) -> str:
    # '{ns}local' -> 'local'
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _remove_layout_cache_from_paragraph(p_el: ET.Element) -> int:
    """Remove any linesegarray / lineseg descendants from the paragraph.

    Returns number of removed elements.
    """

    removed = 0

    # Need parent to remove descendants in ElementTree.
    # Build parent map for this paragraph subtree.
    parent = {c: par for par in p_el.iter() for c in list(par)}

    targets = []
    for el in p_el.iter():
        local = _get_local(el.tag).lower()
        if local in ("linesegarray", "lineseg", "linesegarray".lower(), "lineseg".lower()):
            targets.append(el)

    for el in targets:
        par = parent.get(el)
        if par is None:
            continue
        try:
            par.remove(el)
            removed += 1
        except Exception:
            # best-effort
            pass

    return removed


def _consolidate_and_replace_in_paragraph(
    p_el: ET.Element,
    key_to_value: Dict[str, str],
    stats: ReplaceStats,
) -> bool:
    """If the paragraph contains placeholders, replace and consolidate text.

    - Collect text across <hp:t> nodes, join, replace placeholders.
    - Put final text into first <hp:t> and clear the rest.

    Returns True if paragraph text was modified.
    """

    t_nodes = p_el.findall(".//hp:t", NSMAP)
    if not t_nodes:
        return False

    joined = "".join((t.text or "") for t in t_nodes)
    if "{{" not in joined:
        return False

    original = joined

    def repl(m: re.Match) -> str:
        key = m.group(1)
        if key in key_to_value:
            stats.placeholders_replaced += 1
            return key_to_value[key]
        stats.warnings.append(f"No JSON value for placeholder '{{{{{key}}}}}'")
        return m.group(0)

    replaced = PLACEHOLDER_RE.sub(repl, joined)

    if replaced == original:
        return False

    # Write back: keep first t node, clear the rest
    t_nodes[0].text = replaced
    for t in t_nodes[1:]:
        t.text = ""

    stats.paragraphs_modified += 1
    return True


def process_xml_file(path: Path, key_to_value: Dict[str, str], stats: ReplaceStats) -> bool:
    """Process a single XML file. Returns True if modified."""

    raw = path.read_bytes()
    try:
        root = ET.fromstring(raw)
    except ET.ParseError as e:
        stats.warnings.append(f"XML parse error in {path}: {e}")
        return False

    modified_any = False

    # Only paragraphs need consolidation and layout-cache removal.
    for p_el in root.findall(".//hp:p", NSMAP):
        modified = _consolidate_and_replace_in_paragraph(p_el, key_to_value, stats)
        if modified:
            _remove_layout_cache_from_paragraph(p_el)
            modified_any = True

    if not modified_any:
        return False

    # Preserve XML declaration / encoding utf-8 similar to template.
    xml_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    path.write_bytes(xml_bytes)
    return True


def fill_template(template_path: Path, json_path: Path, output_path: Path) -> ReplaceStats:
    data = json.loads(json_path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError("training_feedback.json must be an object")

    key_to_value: Dict[str, str] = {}
    for k, v in data.items():
        key_to_value[str(k)] = _transform_value(str(k), v)

    stats = ReplaceStats()

    with tempfile.TemporaryDirectory(prefix="hwpx_fill_") as td:
        work = Path(td)

        with zipfile.ZipFile(template_path, "r") as zin:
            zin.extractall(work)

        # Pre-scan for placeholders to warn about unused JSON keys (best-effort)
        xml_text = ""
        for xf in _iter_xml_files(work):
            try:
                xml_text += xf.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                xml_text += xf.read_text(encoding="utf-8", errors="replace")

        placeholders = set(m.group(1) for m in PLACEHOLDER_RE.finditer(xml_text))
        for k in key_to_value.keys():
            if k not in placeholders:
                stats.warnings.append(f"JSON key '{k}' not found as a placeholder in template")

        modified_files = []
        for xf in _iter_xml_files(work):
            if process_xml_file(xf, key_to_value, stats):
                modified_files.append(xf)

        if modified_files:
            stats.files_modified = len(set(modified_files))

        # Repackage to output hwpx (zip)
        # Keep mimetype first/uncompressed if present (none in this template, but handle anyway)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        if output_path.exists():
            output_path.unlink()

        with zipfile.ZipFile(template_path, "r") as zin, zipfile.ZipFile(
            output_path, "w"
        ) as zout:
            names = zin.namelist()

            def write_entry(name: str, compress_type: int):
                src = work / name
                if not src.exists():
                    # Should not happen; skip
                    stats.warnings.append(f"Missing entry during repack: {name}")
                    return
                zi = zipfile.ZipInfo(name)
                # Carry over timestamp/external attrs if possible
                orig_info = zin.getinfo(name)
                zi.date_time = orig_info.date_time
                zi.external_attr = orig_info.external_attr
                zi.compress_type = compress_type
                data = src.read_bytes()
                zout.writestr(zi, data, compress_type=compress_type)

            if "mimetype" in names:
                write_entry("mimetype", compress_type=zipfile.ZIP_STORED)

            for name in names:
                if name == "mimetype":
                    continue
                # Preserve original compression type
                orig = zin.getinfo(name)
                write_entry(name, compress_type=orig.compress_type)

    return stats


def main() -> int:
    stats = fill_template(TEMPLATE_PATH, JSON_PATH, OUTPUT_PATH)

    # Print warnings and stats for visibility
    for w in stats.warnings:
        print("WARN:", w, file=sys.stderr)
    print(
        f"OK: wrote {OUTPUT_PATH} | files_modified={stats.files_modified} paragraphs_modified={stats.paragraphs_modified} placeholders_replaced={stats.placeholders_replaced} warnings={len(stats.warnings)}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
